#!/usr/bin/env python3
"""Collect analysis identities without changing any historical test families."""
import json,hashlib,subprocess,datetime
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'reports/nns_vit_endpoint_revision_v6_r1_20260923'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def committed(p):
 return subprocess.check_output(['git','log','--reverse','--format=%H %cI','--',str(p)],cwd=R,text=True).splitlines()[:1]
def main():
 entries=[]
 configs=[('original_component_and_region','confirmatory','manifests/nns_vit_endpoint/ep0_r1_20260918/statistical_analysis_plan.json','28 tests jointly Holm; 12 component correlations + 16 regional baseline contrasts','fixed GT targets; image inference conditional on selected checkpoints and component rosters'),('unit_depth','confirmatory','config/nns_vit_endpoint/endpoint_m3.json','five per model: entropy, locality, distance, cancellation, CLS-patch entropy','new images conditional on fixed sampled token-channel set'),('attention_residual_depth','confirmatory','config/nns_vit_endpoint/endpoint_m4.json','four attention tests/model; two residual tests/model/type','new images conditional on fixed target and checkpoint'),('head_baselines','exploratory','config/nns_vit_endpoint/endpoint_m1.json','separate paired and absolute Spearman families; other metrics descriptive','within-block heads fixed, image means then image inference'),('residual_spatial_tv','post-hoc','reports/nns_vit_endpoint_m4_review_r2_20260919/freeze.json','four Holm contrasts across model and residual type','image inference for fixed checkpoint and class-target definition'),('QKV_spatial','prospective robustness','reports/nns_vit_endpoint_revision_v3_step2_r2_20260921/freeze.json','30 descriptive contrasts; no confirmatory family combined with prior tests','400 fixed images/model, B11-B0 contrast'),('independent_cohort_checkpoints','prospective robustness','papers/nns_vit_endpoint/thesis_blind_review_20260921/evidence/revision_v5/analysis_estimands.json','H1-H4 Holm separately within each checkpoint','400 independent images, four fixed checkpoints; same team/code/metrics'),('training_target_sampling_controls','exploratory','papers/nns_vit_endpoint/publication_r2_20260920/evidence/supplement_v1/freeze.json','descriptive 2000 bootstrap; training control resamples image and initialization seed; sampling control resamples target strata and images','conditional checks; no training-process causal inference'),('coordinate_sensitivity_v6','prospective robustness','reports/nns_vit_endpoint_revision_v6_r1_20260923/protocol.json','no significance-based success criterion; report all directions and intervals','paired representations within image; fixed original targets and checkpoints'),('threshold_sensitivity_v6','post-hoc','reports/nns_vit_endpoint_revision_v6_r1_20260923/protocol.json','descriptive thresholds only; original tests and decisions immutable','image-level effect distributions')]
 for name,identity,rel,family,pop in configs:
  p=R/rel;d=json.loads(p.read_text());ns=d.get('time_ns');time_text=datetime.datetime.fromtimestamp(ns/1e9,datetime.timezone.utc).isoformat() if ns else d.get('created_utc','local pre-outcome plan; first committed occurrence below')
  entries.append(dict(id=name,identity=identity,source=rel,sha256=sha(p),freeze_time=time_text,first_commit=committed(rel),family=family,inferential_population=pop,external_registration=False))
 plan=json.loads((R/configs[0][2]).read_text())
 data=dict(schema_version=1,analyses=entries,original_tests=plan['tests'],threshold_origin='researcher-selected operational practical-effect thresholds; no external calibration located',composite='valid complete attempted coverage; n_valid>=360; n_nonzero>=300; CI width<=0.30 (association) or <=0.50 (regional); median>=delta; positive direction and original Holm p<=0.05; all four regional baselines must meet conditions; CI lower>delta is a separate stronger statement',intervals='pointwise percentile intervals, not simultaneous familywise intervals',local_freeze_not_external_registration=True)
 (O/'analysis_identity.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+chr(10));print(len(entries),'identities',len(plan['tests']),'original tests')
if __name__=='__main__':main()
